function UserGreeting({ isLoggedIn }) {
  let message;

  if (isLoggedIn) {
    message = <h1>Welcome back!</h1>;
  } else {
    message = <h1>Please sign in.</h1>;
  }

  return (
    <div>
      {message}
      {isLoggedIn && <UserAvatar />}
    </div>
  );
}

function Greeting({ isLoggedIn }) {
  return (
    <div>
      {isLoggedIn ? (
        <h1>Welcome back!</h1>
      ) : (
        <h1>Please sign in.</h1>
      )}
    </div>
  );
}

function Mailbox({ unreadMessages }) {
  return (
    <div>
      <h1>Hello!</h1>
      {unreadMessages.length > 0 && (
        <p>You have {unreadMessages.length} unread messages.</p>
      )}
    </div>
  );
}

// unreadMessages = [] renders nothing
// unreadMessages = [msg1] renders the <p>

function WarningBanner({ showWarning }) {
  if (!showWarning) {
    return null;
  }

  return (
    <div className="warning">
      Warning!
    </div>
  );
}

// Usage
<WarningBanner showWarning={false} /> // renders nothing

function UserProfile({ user }) {
  if (!user) {
    return <p>Loading user...</p>;
  }

  if (user.error) {
    return <div className="error">Failed to load user.</div>;
  }

  return (
    <div className="profile">
      <h1>{user.name}</h1>
      <p>{user.email}</p>
    </div>
  );
}

function StatusMessage({ status }) {
  let message;

  switch (status) {
    case 'loading':
      message = <Spinner />;
      break;
    case 'success':
      message = <SuccessCheckmark />;
      break;
    case 'error':
      message = <ErrorAlert />;
      break;
    default:
      message = null;
  }

  return <div className="status">{message}</div>;
}
